class Solution {
    public int minimumDifference(int[] nums,int k){
        Arrays.sort(nums);
        int answer=Integer.MAX_VALUE;
        for(int right=k-1;right<nums.length;right++)answer=Math.min(answer,nums[right]-nums[right-k+1]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumDifference(nums:IntArray,k:Int):Int{
        nums.sort();
        var answer=Int.MAX_VALUE;
        for(right in k-1 until nums.size)answer=minOf(answer,nums[right]-nums[right-k+1]);
        return answer
    }
}

code.cpp:
class Solution {
    public: int minimumDifference(vector<int>& nums,int k){
        sort(nums.begin(),nums.end());
        int answer=INT_MAX;
        for(int right=k-1;right<(int)nums.size();++right)answer=min(answer,nums[right]-nums[right-k+1]);
        return answer;
    }
};
